@startuml

class SensorController {
}

class Apartment {
  + address : string
  + emailAddress : string
}

class Inhabitant {
  + username : string
  + password : string
}

class Room {
  + description : string
}

class Sensor {
  + vendorId : string
  + description : string
  + unit : Unit
  + threshold : float
}

class TemperatureSensor extends Sensor {
  + min : float
  + max : float
}

class PowerSensor extends Sensor {
  + counterReading : float
}

class MeasuredValue {
  + timestamp : datetime
  + value : float
}

class EMonitor {}

enum Unit {
  CELSIUS
  WATT
}

SensorController "1" -- "*" Apartment : manages
Apartment "1" -- "*" Inhabitant : has
Apartment "1" *-- "2..*" Room : consists of
Room "1" *-- "*" Sensor : contains
Sensor "1" *-- "*" MeasuredValue : records
SensorController "1" -- "*" Sensor : monitors
EMonitor "1" -- "*" Sensor : checks thresholds
EMonitor "1" -- "1" SensorController : sends alerts to

@enduml

